SELECT SUM(CASE WHEN o.currency = 'BDT' THEN o.total_bdt ELSE o.total_amount * ( SELECT x.bdt_per_unit FROM currency_rates x WHERE x.rate_date = CAST(o.order_at AS DATE) AND x.currency = o.currency) END) AS v FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2025-04-01 00:00:00' AND o.order_at < TIMESTAMP '2025-05-01 00:00:00'
